189: struct Execution {
190:     stack: Vec<String>,
191: }
192: 
193: impl Execution {
194:     pub fn new(logs: &mut &[String]) -> Result<Self, ClientError> {
195:         let l = &logs[0];
196:         *logs = &logs[1..];
197: 
198:         let re = Regex::new(r"^Program (.*) invoke.*$").unwrap();
199:         let c = re
200:             .captures(l)
201:             .ok_or_else(|| ClientError::LogParseError(l.to_string()))?;
202:         let program = c
203:             .get(1)
204:             .ok_or_else(|| ClientError::LogParseError(l.to_string()))?
205:             .as_str()
206:             .to_string();
207:         Ok(Self {
208:             stack: vec![program],
209:         })
210:     }
211: 
212:     pub fn program(&self) -> String {
213:         assert!(!self.stack.is_empty());
214:         self.stack[self.stack.len() - 1].clone()
215:     }
216: 
217:     pub fn push(&mut self, new_program: String) {
218:         self.stack.push(new_program);
219:     }
220: 
221:     pub fn pop(&mut self) {
222:         assert!(!self.stack.is_empty());
223:         self.stack.pop().unwrap();
224:     }
225: }
