23: impl<C: Deref<Target = impl Signer> + Clone> Program<C> {
24:     /// Returns the account at the given address.
25:     pub fn account<T: AccountDeserialize>(&self, address: Pubkey) -> Result<T, ClientError> {
26:         let rpc_client = RpcClient::new_with_commitment(
27:             self.cfg.cluster.url().to_string(),
28:             self.cfg.options.unwrap_or_default(),
29:         );
30:         let account = rpc_client
31:             .get_account_with_commitment(&address, CommitmentConfig::processed())?
32:             .value
33:             .ok_or(ClientError::AccountNotFound)?;
34:         let mut data: &[u8] = &account.data;
35:         T::try_deserialize(&mut data).map_err(Into::into)
36:     }
37: 
38:     /// Returns all program accounts of the given type matching the given filters
39:     pub fn accounts<T: AccountDeserialize + Discriminator>(
40:         &self,
41:         filters: Vec<RpcFilterType>,
42:     ) -> Result<Vec<(Pubkey, T)>, ClientError> {
43:         self.accounts_lazy(filters)?.collect()
44:     }
45: 
46:     /// Returns all program accounts of the given type matching the given filters as an iterator
47:     /// Deserialization is executed lazily
48:     pub fn accounts_lazy<T: AccountDeserialize + Discriminator>(
49:         &self,
50:         filters: Vec<RpcFilterType>,
51:     ) -> Result<ProgramAccountsIterator<T>, ClientError> {
52:         let account_type_filter =
53:             RpcFilterType::Memcmp(Memcmp::new_base58_encoded(0, &T::discriminator()));
54:         let config = RpcProgramAccountsConfig {
55:             filters: Some([vec![account_type_filter], filters].concat()),
56:             account_config: RpcAccountInfoConfig {
57:                 encoding: Some(UiAccountEncoding::Base64),
58:                 ..RpcAccountInfoConfig::default()
59:             },
60:             ..RpcProgramAccountsConfig::default()
61:         };
62:         Ok(ProgramAccountsIterator {
63:             inner: self
64:                 .rpc()
65:                 .get_program_accounts_with_config(&self.id(), config)?
66:                 .into_iter()
67:                 .map(|(key, account)| {
68:                     Ok((key, T::try_deserialize(&mut (&account.data as &[u8]))?))
69:                 }),
70:         })
71:     }
