73:     pub fn rpc(&self) -> RpcClient {
74:         RpcClient::new_with_commitment(
75:             self.cfg.cluster.url().to_string(),
76:             self.cfg.options.unwrap_or_default(),
77:         )
78:     }
79: 
80:     pub fn on<T: anchor_lang::Event + anchor_lang::AnchorDeserialize>(
81:         &self,
82:         f: impl Fn(&EventContext, T) + Send + 'static,
83:     ) -> Result<EventHandle, ClientError> {
84:         let addresses = vec![self.program_id.to_string()];
85:         let filter = RpcTransactionLogsFilter::Mentions(addresses);
86:         let ws_url = self.cfg.cluster.ws_url().to_string();
87:         let cfg = RpcTransactionLogsConfig {
88:             commitment: self.cfg.options,
89:         };
90:         let self_program_str = self.program_id.to_string();
91:         let (client, receiver) = PubsubClient::logs_subscribe(&ws_url, filter, cfg)?;
92:         std::thread::spawn(move || {
93:             loop {
94:                 match receiver.recv() {
95:                     Ok(logs) => {
96:                         let ctx = EventContext {
97:                             signature: logs.value.signature.parse().unwrap(),
98:                             slot: logs.context.slot,
99:                         };
100:                         let mut logs = &logs.value.logs[..];
101:                         if !logs.is_empty() {
102:                             if let Ok(mut execution) = Execution::new(&mut logs) {
103:                                 for l in logs {
104:                                     // Parse the log.
105:                                     let (event, new_program, did_pop) = {
106:                                         if self_program_str == execution.program() {
107:                                             handle_program_log(&self_program_str, l).unwrap_or_else(
108:                                                 |e| {
109:                                                     println!("Unable to parse log: {e}");
110:                                                     std::process::exit(1);
111:                                                 },
112:                                             )
113:                                         } else {
114:                                             let (program, did_pop) =
115:                                                 handle_system_log(&self_program_str, l);
116:                                             (None, program, did_pop)
117:                                         }
118:                                     };
119:                                     // Emit the event.
120:                                     if let Some(e) = event {
121:                                         f(&ctx, e);
122:                                     }
123:                                     // Switch program context on CPI.
124:                                     if let Some(new_program) = new_program {
125:                                         execution.push(new_program);
126:                                     }
127:                                     // Program returned.
128:                                     if did_pop {
129:                                         execution.pop();
130:                                     }
131:                                 }
132:                             }
133:                         }
134:                     }
135:                     Err(_err) => {
136:                         return;
137:                     }
138:                 }
139:             }
140:         });
141:         Ok(client)
142:     }
143: }
