134: fn handle_program_log<T: anchor_lang::Event + anchor_lang::AnchorDeserialize>(
135:     self_program_str: &str,
136:     l: &str,
137: ) -> Result<(Option<T>, Option<String>, bool), ClientError> {
138:     // Log emitted from the current program.
139:     if let Some(log) = l
140:         .strip_prefix(PROGRAM_LOG)
141:         .or_else(|| l.strip_prefix(PROGRAM_DATA))
142:     {
143:         let borsh_bytes = match anchor_lang::__private::base64::decode(log) {
144:             Ok(borsh_bytes) => borsh_bytes,
145:             _ => {
146:                 #[cfg(feature = "debug")]
147:                 println!("Could not base64 decode log: {}", log);
148:                 return Ok((None, None, false));
149:             }
150:         };
151: 
152:         let mut slice: &[u8] = &borsh_bytes[..];
153:         let disc: [u8; 8] = {
154:             let mut disc = [0; 8];
155:             disc.copy_from_slice(&borsh_bytes[..8]);
156:             slice = &slice[8..];
157:             disc
158:         };
159:         let mut event = None;
160:         if disc == T::discriminator() {
161:             let e: T = anchor_lang::AnchorDeserialize::deserialize(&mut slice)
162:                 .map_err(|e| ClientError::LogParseError(e.to_string()))?;
163:             event = Some(e);
164:         }
165:         Ok((event, None, false))
166:     }
167:     // System log.
168:     else {
169:         let (program, did_pop) = handle_system_log(self_program_str, l);
170:         Ok((None, program, did_pop))
171:     }
